// ---------------- logging ----------------
static LOG_LEVEL: std::sync::atomic::AtomicU8 = std::sync::atomic::AtomicU8::new(0);
fn set_log_level(v: u8) { LOG_LEVEL.store(v, std::sync::atomic::Ordering::SeqCst); }
fn log_level() -> u8 { LOG_LEVEL.load(std::sync::atomic::Ordering::SeqCst) }
fn timestamp_now() -> String {
    let secs = SystemTime::now().duration_since(UNIX_EPOCH).map(|d| d.as_secs() as i64).unwrap_or(0);
    let days = secs.div_euclid(86400);
    let rem = secs.rem_euclid(86400);
    let (h, mi, s) = (rem / 3600, (rem % 3600) / 60, rem % 60);
    // civil from days (Howard Hinnant algorithm)
    let z = days + 719468;
    let era = if z >= 0 { z } else { z - 146096 } / 146097;
    let doe = z - era * 146097;
    let yoe = (doe - doe/1460 + doe/36524 - doe/146096) / 365;
    let y = yoe + era * 400;
    let doy = doe - (365*yoe + yoe/4 - yoe/100);
    let mp = (5*doy + 2)/153;
    let d = doy - (153*mp+2)/5 + 1;
    let m = if mp < 10 { mp + 3 } else { mp - 9 };
    let y = if m <= 2 { y + 1 } else { y };
    format!("{:04}-{:02}-{:02}T{:02}:{:02}:{:02}Z", y, m, d, h, mi, s)
}
fn log_msg(level_name: &str, level_val: u8, target: &str, msg: &str) {
    if log_level() < level_val { return; }
    // level_val: 1=ERROR? we use mapping: error shown at >=0? We'll call with required level.
    eprintln!("[{} {:<5} {}] {}", timestamp_now(), level_name, target, msg);
}
fn log_error(target: &str, msg: &str) { eprintln!("[{} {:<5} {}] {}", timestamp_now(), "ERROR", target, msg); }
fn log_warn(target: &str, msg: &str) { if log_level() >= 1 { eprintln!("[{} {:<5} {}] {}", timestamp_now(), "WARN", target, msg); } }
fn log_debug(target: &str, msg: &str) { if log_level() >= 2 { eprintln!("[{} {:<5} {}] {}", timestamp_now(), "DEBUG", target, msg); } }

// ---------------- stats ----------------
#[derive(Clone, Debug, Default, PartialEq)]
struct Stats {
    blanks: usize,
    code: usize,
    comments: usize,
    blobs: BTreeMap<String, Stats>,
}
impl Stats {
    fn lines(&self) -> usize { self.blanks + self.code + self.comments }
    fn add_main(&mut self, o: &Stats) { self.blanks += o.blanks; self.code += o.code; self.comments += o.comments; }
    fn merge_from(&mut self, o: &Stats) {
        self.add_main(o);
        for (k, v) in &o.blobs {
            self.blobs.entry(k.clone()).or_default().merge_from(v);
        }
    }
    fn recursive_totals(&self) -> (usize, usize, usize) {
        let mut b = self.blanks; let mut c = self.code; let mut cm = self.comments;
        for v in self.blobs.values() {
            let (bb, cc, mm) = v.recursive_totals(); b += bb; c += cc; cm += mm;
        }
        (b, c, cm)
    }
}
#[derive(Clone, Debug)]
struct Report { name: String, stats: Stats }
#[derive(Clone, Debug, Default)]
struct LangEntry {
    name: String,
    blanks: usize, code: usize, comments: usize,
    reports: Vec<Report>,
    children: BTreeMap<String, Vec<Report>>,
    inaccurate: bool,
}
impl LangEntry {
    fn lines(&self) -> usize { self.blanks + self.code + self.comments }
    fn recursive_totals(&self) -> (usize, usize, usize) {
        let mut b=0; let mut c=0; let mut cm=0;
        for r in &self.reports { let (bb,cc,mm)=r.stats.recursive_totals(); b+=bb; c+=cc; cm+=mm; }
        (b,c,cm)
    }
}

// ---------------- language lookups ----------------
fn lang_by_name(name: &str) -> Option<usize> {
    static MAP: OnceLock<HashMap<String, usize>> = OnceLock::new();
    let m = MAP.get_or_init(|| {
        let mut h = HashMap::new();
        for (i,l) in LANGS.iter().enumerate() { h.insert(l.name.to_lowercase(), i); }
        h
    });
    m.get(&name.to_lowercase()).copied()
}
fn lang_index(name: &str) -> usize { lang_by_name(name).expect("known language") }
fn ext_map() -> &'static HashMap<String, usize> {
    static MAP: OnceLock<HashMap<String, usize>> = OnceLock::new();
    MAP.get_or_init(|| {
        let mut h = HashMap::new();
        for (i,l) in LANGS.iter().enumerate() {
            for e in l.extensions {
                if e.contains('.') { continue; }
                let k = e.to_lowercase().replace('\u{200b}', "");
                h.entry(k).or_insert(i);
            }
        }
        // emoji extension without the zero-width joiner used in display text
        if let Some(i) = lang_by_name("Emojicode") { h.insert("🍇".to_string(), i); }
        h
    })
}
fn filename_map() -> &'static HashMap<String, usize> {
    static MAP: OnceLock<HashMap<String, usize>> = OnceLock::new();
    MAP.get_or_init(|| {
        let mut h = HashMap::new();
        let pairs: &[(&str,&str)] = &[
            ("makefile","Makefile"),("gnumakefile","Makefile"),
            ("cmakelists.txt","CMake"),
            ("meson.build","Meson"),("meson_options.txt","Meson"),
            ("dockerfile","Dockerfile"),
            ("justfile","Just"),
            ("rakefile","Rakefile"),
            ("sconstruct","Scons"),("sconscript","Scons"),
            ("pkgbuild","Pacman's makepkg"),
            ("build","Bazel"),("workspace","Bazel"),("module","Bazel"),
            ("snakefile","Snakemake"),
            ("nuget.config","NuGet Config"),("packages.config","NuGet Config"),
        ];
        for (file, lang) in pairs { if let Some(i)=lang_by_name(lang) { h.insert(file.to_string(), i); } }
        h
    })
}

// ------------- token preparation -------------
#[derive(Clone, Debug)]
enum TokKind { Doc, Line, Block(usize), Quote(usize) }
#[derive(Clone, Debug)]
struct Token { text: &'static str, kind: TokKind }
fn token_sets() -> &'static Vec<Vec<Token>> {
    static SETS: OnceLock<Vec<Vec<Token>>> = OnceLock::new();
    SETS.get_or_init(|| {
        LANGS.iter().map(|l| {
            let mut v: Vec<Token> = Vec::new();
            if l.rust_doc { v.push(Token{text:"///", kind:TokKind::Doc}); v.push(Token{text:"//!", kind:TokKind::Doc}); }
            for t in l.line { v.push(Token{text:t, kind:TokKind::Line}); }
            for (i,(s,_,_)) in l.blocks.iter().enumerate() { v.push(Token{text:s, kind:TokKind::Block(i)}); }
            for (i,(s,_)) in l.quotes.iter().enumerate() { v.push(Token{text:s, kind:TokKind::Quote(i)}); }
            v.sort_by(|a,b| b.text.len().cmp(&a.text.len()));
            v
        }).collect()
    })
}

// ------------- counting: normal -------------
#[derive(Clone, Debug)]
enum Frame {
    Comment { start: &'static str, end: &'static str, nested: bool, depth: usize },
    Quote { end: &'static str, start: &'static str },
}
#[derive(PartialEq)]
enum LineClass { Code, Comment, Blank }
fn count_normal(lang_idx: usize, content: &str) -> Stats {
    let lang = &LANGS[lang_idx];
    match lang.kind {
        1 => { // plain text-like
            let mut st = Stats::default();
            for line in content.lines() { if line.trim().is_empty() { st.blanks+=1; } else { st.comments+=1; } }
            return st;
        }
        2 => return count_markdown(lang_idx, content),
        3|4|5 => return count_html_like(lang_idx, content),
        6 => return count_jupyter(content),
        _ => {}
    }
    count_simple(lang_idx, content)
}
fn count_simple(lang_idx: usize, content: &str) -> Stats {
    let lang = &LANGS[lang_idx];
    let toks = &token_sets()[lang_idx];
    let mut stats = Stats::default();
    let mut stack: Vec<Frame> = Vec::new();
    let mut doc_lines: Vec<String> = Vec::new();
    let mut doc_found = false;
    for line in content.lines() {
        if line.trim().is_empty() {
            match stack.last() {
                Some(Frame::Comment{..}) => stats.comments+=1,
                Some(Frame::Quote{..}) => stats.code+=1,
                None => stats.blanks+=1,
            }
            continue;
        }
        let start_in_comment = matches!(stack.last(), Some(Frame::Comment{..}));
        let start_in_quote = matches!(stack.last(), Some(Frame::Quote{..}));
        // scan line
        let bytes = line.as_bytes();
        let mut pos: usize = 0;
        let mut has_code = false;
        let mut has_comment = false;
        let mut is_doc: Option<String> = None;
        // Does the (trimmed, or raw for fortran) line start with a block comment?
        let check_line = if lang.no_trim { line } else { line.trim_start() };
        let starts_with_block = if stack.is_empty() {
            lang.blocks.iter().any(|(s,_,_)| check_line.starts_with(s))
        } else { false };
        'scan: while pos < line.len() {
            // current frame
            let frame_kind = match stack.last() { Some(Frame::Comment{..}) => 1, Some(Frame::Quote{..}) => 2, None => 0 };
            if frame_kind == 2 {
                let end = if let Some(Frame::Quote{end,..}) = stack.last() { *end } else { "" };
                let start_tok = if let Some(Frame::Quote{start,..}) = stack.last() { *start } else { "" };
                has_code = true;
                if line[pos..].starts_with(end) {
                    stack.pop(); pos += end.len(); continue 'scan;
                }
                if bytes[pos] == b'\\' && !start_tok.contains('#') {
                    // skip escaped character
                    pos += 1;
                    if pos < line.len() { let chlen = line[pos..].chars().next().map(|c| c.len_utf8()).unwrap_or(1); pos += chlen; }
                    continue 'scan;
                }
                let chlen = line[pos..].chars().next().map(|c| c.len_utf8()).unwrap_or(1); pos += chlen; continue 'scan;
            }
            if frame_kind == 1 {
                has_comment = true;
                let (start_tok, end_tok, nested) = if let Some(Frame::Comment{start,end,nested,..}) = stack.last() { (*start,*end,*nested) } else { ("","",false) };
                if line[pos..].starts_with(end_tok) {
                    if let Some(Frame::Comment{depth,..}) = stack.last_mut() { *depth -= 1; if *depth==0 { stack.pop(); } }
                    pos += end_tok.len(); continue 'scan;
                }
                if nested && line[pos..].starts_with(start_tok) {
                    if let Some(Frame::Comment{depth,..}) = stack.last_mut() { *depth += 1; }
                    pos += start_tok.len(); continue 'scan;
                }
                let chlen = line[pos..].chars().next().map(|c| c.len_utf8()).unwrap_or(1); pos += chlen; continue 'scan;
            }
            // outside any frame
            // Find a token at pos
            let mut matched: Option<Token> = None;
            for t in toks {
                if line[pos..].starts_with(t.text) { matched = Some(t.clone()); break; }
            }
            if let Some(tok) = matched {
                match tok.kind {
                    TokKind::Doc => {
                        is_doc = Some(line[pos+tok.text.len()..].to_string());
                        doc_found = true;
                        break 'scan;
                    }
                    TokKind::Line => {
                        // FORTRAN style: a line comment token is not recognised after leading whitespace at start of line.
                        if lang.no_trim && !has_code && !has_comment {
                            // check if this token begins after whitespace only and not at column 0
                            if pos != 0 {
                                has_code = true; pos += tok.text.len(); continue 'scan;
                            }
                        }
                        has_comment = true;
                        break 'scan;
                    }
                    TokKind::Block(i) => {
                        has_comment = true;
                        let (s,e,n) = lang.blocks[i];
                        stack.push(Frame::Comment{start:s,end:e,nested:n,depth:1});
                        pos += tok.text.len(); continue 'scan;
                    }
                    TokKind::Quote(i) => {
                        has_code = true;
                        let (s,e) = lang.quotes[i];
                        stack.push(Frame::Quote{end:e,start:s});
                        pos += tok.text.len(); continue 'scan;
                    }
                }
            }
            // no token
            if !line[pos..].chars().next().map(|c| c.is_whitespace()).unwrap_or(false) { has_code = true; }
            let chlen = line[pos..].chars().next().map(|c| c.len_utf8()).unwrap_or(1); pos += chlen;
        }
        if let Some(doc) = is_doc {
            doc_lines.push(doc);
            continue;
        }
        let class = if start_in_quote { LineClass::Code } else if start_in_comment { LineClass::Comment } else if has_code {
            // sandwich rule: starts and ends with a block comment
            let trimmed = line.trim();
            let ends_with_block = lang.blocks.iter().any(|(_,e,_)| !e.is_empty() && trimmed.ends_with(e));
            if starts_with_block && ends_with_block && stack.is_empty() && has_comment { LineClass::Comment } else { LineClass::Code }
        } else if has_comment { LineClass::Comment } else { LineClass::Blank };
        match class { LineClass::Code=>stats.code+=1, LineClass::Comment=>stats.comments+=1, LineClass::Blank=>stats.blanks+=1 }
    }
    if lang.rust_doc && doc_found {
        let joined = doc_lines.join("\n");
        let trimmed = joined.trim_start().to_string();
        let md_idx = lang_index("Markdown");
        let md_stats = count_markdown(md_idx, &trimmed);
        stats.blobs.insert("Markdown".to_string(), md_stats);
    }
    stats
}

// ------------- markdown -------------
fn fence_language(rest: &str) -> Option<(usize, Option<String>)> {
    // rest is text after ``` on the opening line (not trimmed at start)
    if rest.is_empty() { return None; }
    // first whitespace position
    let ws_idx = rest.find(|c: char| c==' ' || c=='\t');
    let (head, tail) = match ws_idx { Some(i)=>( &rest[..i], Some(rest[i..].trim_start_matches(|c| c==' '||c=='\t').to_string())), None=>(rest, None) };
    let candidate = head.split(',').next().unwrap_or("");
    if candidate.is_empty() { return None; }
    if let Some(idx) = lang_by_name(candidate) {
        // Tail that is empty string should be treated as none
        let tail = tail.and_then(|t| if t.is_empty() { None } else { Some(t) });
        return Some((idx, tail));
    }
    None
}
fn count_markdown(_lang_idx: usize, content: &str) -> Stats {
    let mut stats = Stats::default();
    let mut in_fence: Option<(usize, Vec<String>, Option<String>)> = None; // lang, buffer lines, initial tail
    for line in content.lines() {
        if let Some((lang_idx, buf, _)) = &mut in_fence {
            if line.trim_start().starts_with("```") {
                stats.comments += 1;
                let (lidx, buffer, tail) = in_fence.take().unwrap();
                let mut text = String::new();
                if let Some(t) = tail { text.push_str(&t); text.push('\n'); }
                text.push_str(&buffer.join("\n"));
                let counted = count_normal(lidx, text.trim());
                stats.blobs.entry(LANGS[lidx].name.to_string()).or_default().merge_from(&counted);
                let _ = lang_idx;
            } else {
                buf.push(line.to_string());
            }
            continue;
        }
        if line.trim().is_empty() { stats.blanks += 1; continue; }
        let trimmed_start = line.trim_start();
        if trimmed_start.starts_with("```") {
            stats.comments += 1;
            if let Some((lidx, tail)) = fence_language(&trimmed_start[3..]) {
                in_fence = Some((lidx, Vec::new(), tail));
                // Ensure blob entry exists even for empty fences (created at close/EOF); we mark by inserting now if fence never closes? We'll insert at finish.
            }
            continue;
        }
        stats.comments += 1;
    }
    if let Some((lidx, buffer, tail)) = in_fence {
        let mut text = String::new();
        if let Some(t) = tail { text.push_str(&t); text.push('\n'); }
        text.push_str(&buffer.join("\n"));
        let counted = count_normal(lidx, text.trim());
        stats.blobs.entry(LANGS[lidx].name.to_string()).or_default().merge_from(&counted);
    }
    stats
}

// ------------- HTML-like -------------
fn find_tag_end(content: &str, start: usize) -> Option<usize> {
    // return index just after '>' if there is a '>' before a newline
    let rest = &content[start..];
    let gt = rest.find('>')?;
    let nl = rest.find('\n').unwrap_or(usize::MAX);
    if gt < nl { Some(start + gt + 1) } else { None }
}
fn lang_attr(tag_text: &str) -> Option<usize> {
    // find lang="..." such that after closing quote there is no '"' before '>'
    let mut search_from = 0usize;
    let mut result = None;
    while let Some(pos) = tag_text[search_from..].find("lang=\"") {
        let pos = search_from + pos;
        let val_start = pos + 6;
        if let Some(q) = tag_text[val_start..].find('"') {
            let val = &tag_text[val_start..val_start+q];
            let after = &tag_text[val_start+q+1..];
            // strip closing '>' for check
            let after_no_gt = after.strip_suffix('>').unwrap_or(after);
            if !after_no_gt.contains('"') {
                if let Some(idx) = lang_by_name(val.trim()) { result = Some(idx); }
            }
            search_from = val_start + q + 1;
        } else { break; }
    }
    result
}
fn script_lang(tag_text: &str) -> usize {
    // search type="..." with same no-later-quote rule
    let mut search_from = 0usize;
    let mut chosen: Option<String> = None;
    while let Some(pos) = tag_text[search_from..].find("type=\"") {
        let pos = search_from + pos;
        let val_start = pos + 6;
        if let Some(q) = tag_text[val_start..].find('"') {
            let val = &tag_text[val_start..val_start+q];
            let after = &tag_text[val_start+q+1..];
            let after_no_gt = after.strip_suffix('>').unwrap_or(after);
            if !after_no_gt.contains('"') { chosen = Some(val.to_string()); }
            search_from = val_start + q + 1;
        } else { break; }
    }
    if let Some(v) = chosen {
        match v.as_str() {
            "application/json" => return lang_index("JSON"),
            "text/html" => return lang_index("HTML"),
            "text/plain" => return lang_index("Plain Text"),
            _ => {}
        }
    }
    lang_index("JavaScript")
}
fn count_html_like(lang_idx: usize, content: &str) -> Stats {
    // Line-fragment model
    let kind = LANGS[lang_idx].kind;
    let allowed: &[(&str,&str)] = match kind { 4 => &[("script","</script>"),("style","</style>"),("template","</template>")], 5 => &[("template","</template>"),("style","</style>")], _ => &[("script","</script>"),("style","</style>")] };
    let lines: Vec<&str> = content.lines().collect();
    let mut parent_text = String::new();
    let mut blobs: BTreeMap<String, Stats> = BTreeMap::new();
    let mut parent_stats_extra_blanks: usize = 0;
    // state
    let mut child: Option<(usize, String, String)> = None; // lang index, closing tag, text buffer
    // To validate unterminated openings, we need to know if closing exists later. We'll check remaining content globally via a simple search in the remaining lines text.
    // Build a joined remaining string for searches (cheap enough for typical files)
    let full_remaining = |from_line: usize, from_pos: usize, lines: &Vec<&str>| -> String {
        let mut s = String::new();
        if from_line < lines.len() { s.push_str(&lines[from_line][from_pos..]); s.push('\n'); for l in &lines[from_line+1..] { s.push_str(l); s.push('\n'); } }
        s
    };
    for li in 0..lines.len() {
        let line = lines[li];
        let mut pos: usize = 0;
        // parent syntax stack persists across parent fragments on different lines, but our parent_text counting recomputes it,
        // so for tag detection inside comments / quotes we need a detection stack here as well.
        // We maintain it as a separate stack updated while scanning parent segments of this line (and across lines).
        // To simplify across lines, store it outside loop.
        // (declared below outside loop in actual state via a persistent variable - we use a trick: static thread_local not needed; we keep a variable in outer scope)
        // NOTE: parent_stack is defined outside for-loop (see below variable shadowing via a mutable captured variable is not possible here, so we reconstruct logic inside loop using a persistent field stored in child tuple? )
        // Instead, we handle parent comments/quotes by scanning parent_text? No.
        // We'll do scanning with a stack kept in a variable that lives across lines: we create it before loop in code (rust will move it) - this comment is placeholder.
        let _ = full_remaining;
        // The actual scanning for this line:
        let mut frag_start: usize = 0; // start of current segment in line (for the current mode)
        let mut i: usize = 0;
        // We need parent_stack accessible - it is stored in a variable defined before the loop (named parent_stack)
        // Rust: this loop uses it via mutable reference (declared earlier). See code below: parent_stack variable is created before loop.
        // (This inner code references it.)
        loop {
            if let Some((clidx, closing, _buf)) = child.clone() {
                // searching closing in line[i..]
                if let Some(found) = line[i..].find(&closing) {
                    let cpos = i + found;
                    let frag = &line[frag_start..cpos];
                    if !frag.is_empty() {
                        if let Some((_,_,buf)) = &mut child { buf.push_str(frag); buf.push('\n'); }
                    }
                    // close child block
                    let (cl, _close, buf) = child.take().unwrap();
                    if buf.trim().is_empty() {
                        // count blank lines in buf as parent blanks
                        parent_stats_extra_blanks += buf.lines().count();
                    } else {
                        let counted = count_normal(cl, &buf);
                        blobs.entry(LANGS[cl].name.to_string()).or_default().merge_from(&counted);
                    }
                    let _ = clidx;
                    // parent fragment starts at cpos
                    frag_start = cpos;
                    i = cpos;
                    // fallthrough to parent scanning
                } else {
                    // whole rest is child
                    let frag = &line[frag_start..];
                    if frag.is_empty() {
                        if let Some((_,_,buf)) = &mut child { buf.push('\n'); }
                    } else {
                        if let Some((_,_,buf)) = &mut child { buf.push_str(frag); buf.push('\n'); }
                    }
                    break;
                }
            }
            // parent mode scanning from i
            // If we are at end
            if i >= line.len() {
                // append final parent fragment
                let frag = &line[frag_start..];
                if !frag.is_empty() { parent_text.push_str(frag); parent_text.push('\n'); }
                else if child.is_none() && frag_start==0 {
                    // a blank line in parent mode (entire line empty) - only if we are in parent mode at line start
                    // Determine: if line is empty and we never entered child, it's parent blank represented as an empty line in parent_text
                    // However if the line was a child->parent transition with empty frag, not.
                    // Our frag_start==0 and child is none at this point could also happen after closing a child at position 0 with empty parent frag, which is not a blank parent line.
                    // To avoid double counting, only add when line is empty and no child was closed on this line: we can check line.is_empty()
                    if line.is_empty() { parent_text.push('\n'); }
                }
                break;
            }
            // parent syntax scanning advance until a tag or end
            // We scan char by char using parent_stack
            let mut advanced = false;
            // Check for tag at i (only when parent_stack empty)
            let parent_stack_empty = PARENT_STACK.with(|_| true); // placeholder replaced below
            let _ = parent_stack_empty;
            break;
        }
        let _ = pos; let _ = frag_start;
    }
    // The above line-fragment approach was replaced by segment approach below (see count_html_segments)
    let _ = (parent_text.clone(), blobs.clone(), parent_stats_extra_blanks);
    count_html_segments(lang_idx, content)
}
thread_local! {
    static PARENT_STACK: std::cell::RefCell<Vec<Frame>> = std::cell::RefCell::new(Vec::new());
}
fn count_html_segments(lang_idx: usize, content: &str) -> Stats {
    let kind = LANGS[lang_idx].kind;
    let allowed: &[(&str,&str)] = match kind { 4 => &[("script","</script>"),("style","</style>"),("template","</template>")], 5 => &[("template","</template>"),("style","</style>")], _ => &[("script","</script>"),("style","</style>")] };
    let mut stats = Stats::default();
    let mut blobs: BTreeMap<String, Stats> = BTreeMap::new();
    let mut pos: usize = 0; // start of parent segment
    let mut search_from: usize = 0;
    // Helper to detect if a "<script" at byte idx is inside a parent comment <!-- --> that started earlier in content up to idx
    // We approximate by scanning parent segments normally: our segment search will not special-case comments fully,
    // but we handle a simple case: if the text before tag in the current parent segment contains an unterminated "<!--" (for HTML-like languages with that block) and no "-->" after it, skip tag.
    loop {
        // find next opening candidate
        let mut found: Option<(usize, usize, &'static str, &'static str, String)> = None; // tag_start, tag_end, name, closing, tag_text
        let mut cur = search_from;
        'search: while cur < content.len() {
            let mut best: Option<(usize,&str,&str)> = None;
            for (name, closing) in allowed {
                let pat = format!("<{}", name);
                if let Some(idx) = content[cur..].find(&pat) {
                    let idx = cur + idx;
                    if best.map(|(b,_,_)| idx < b).unwrap_or(true) { best = Some((idx, name, closing)); }
                }
            }
            let (idx, name, closing) = match best { Some(v)=>v, None=>break 'search };
            // validate char after name
            let after_name = idx + 1 + name.len();
            if after_name < content.len() {
                let ch = content.as_bytes()[after_name];
                if ch.is_ascii_alphanumeric() || ch == b'_' { cur = after_name; continue 'search; }
            }
            let tag_end = match find_tag_end(content, idx) { Some(v)=>v, None=>{ cur = after_name; continue 'search; } };
            let tag_text = content[idx..tag_end].to_string();
            // closing must exist after tag_end
            if content[tag_end..].find(closing).is_none() { cur = after_name; continue 'search; }
            // check for unterminated HTML comment before tag in the current parent segment
            if LANGS[lang_idx].blocks.iter().any(|(s,_ ,_)| s=="<!--") {
                let seg = &content[pos..idx];
                if let Some(cstart) = seg.rfind("<!--") {
                    if !seg[cstart..].contains("-->") { cur = after_name; continue 'search; }
                }
            }
            found = Some((idx, tag_end, name, closing, tag_text));
            break 'search;
        }
        let (tag_start, tag_end, name, closing, tag_text) = match found { Some(v)=>v, None=>break };
        // parent segment up to and including opening tag
        let parent_seg = &content[pos..tag_end];
        let pstats = count_simple(lang_idx, parent_seg);
        stats.add_main(&pstats); for (k,v) in pstats.blobs { stats.blobs.entry(k).or_default().merge_from(&v); }
        // child content
        let close_start = content[tag_end..].find(closing).map(|i| tag_end+i).unwrap();
        let child_content_raw = &content[tag_end..close_start];
        let child_content = child_content_raw.strip_prefix("\r\n").or_else(|| child_content_raw.strip_prefix('\n')).unwrap_or(child_content_raw);
        let child_idx = match name {
            "script" => script_lang(&tag_text),
            "style" => lang_attr(&tag_text).unwrap_or_else(|| lang_index("CSS")),
            "template" => lang_attr(&tag_text).unwrap_or_else(|| lang_index("HTML")),
            _ => lang_index("JavaScript"),
        };
        if !child_content.trim().is_empty() {
            let counted = count_normal(child_idx, child_content);
            blobs.entry(LANGS[child_idx].name.to_string()).or_default().merge_from(&counted);
        } else {
            // blank-only content contributes blank lines to parent (the lines between tag lines)
            // Count blank lines: number of lines in child_content_raw after stripping first newline
            let cc = child_content;
            if !cc.is_empty() {
                // each line in cc that is blank (all are) counts
                let n = cc.lines().count();
                stats.blanks += n;
            }
        }
        // resume parent segment at closing tag
        pos = close_start;
        search_from = close_start + closing.len();
    }
    let parent_seg = &content[pos..];
    if !parent_seg.is_empty() || pos==0 {
        let pstats = count_simple(lang_idx, parent_seg);
        stats.add_main(&pstats); for (k,v) in pstats.blobs { stats.blobs.entry(k).or_default().merge_from(&v); }
    }
    stats.blobs = blobs;
    stats
}

// ------------- jupyter -------------
#[derive(Deserialize)]
struct Nb { cells: Vec<NbCell>, metadata: NbMeta }
#[derive(Deserialize)]
struct NbMeta { kernelspec: NbKs, language_info: serde_json::Value }
#[derive(Deserialize)]
struct NbKs { language: Option<String> }
#[derive(Deserialize)]
struct NbCell { cell_type: String, source: Vec<String> }
fn count_jupyter(content: &str) -> Stats {
    let nb: Nb = match serde_json::from_str(content) { Ok(v)=>v, Err(_)=>return Stats::default() };
    let kernel_lang_name = nb.metadata.kernelspec.language.as_deref().unwrap_or("");
    let kernel_idx = lang_by_name(kernel_lang_name).unwrap_or_else(|| lang_index("Python"));
    let md_idx = lang_index("Markdown");
    let mut stats = Stats::default();
    for cell in &nb.cells {
        let src = cell.source.concat();
        let lidx = match cell.cell_type.as_str() { "markdown"=>md_idx, "code"=>kernel_idx, _=>continue };
        let counted = count_normal(lidx, &src);
        stats.add_main(&counted);
        stats.blobs.entry(LANGS[lidx].name.to_string()).or_default().merge_from(&counted);
        for (k,v) in &counted.blobs {
            stats.blobs.entry(k.clone()).or_default().merge_from(v);
        }
    }
    stats
}

// ------------- file detection / reading -------------
fn decode_bytes(bytes: &[u8]) -> String {
    if bytes.starts_with(&[0xFF, 0xFE]) {
        // UTF-16 LE (also handles UTF-32 BOM as UTF-16, matching reference behaviour)
        let units: Vec<u16> = bytes[2..].chunks_exact(2).map(|c| u16::from_le_bytes([c[0],c[1]])).collect();
        return String::from_utf16_lossy(&units);
    }
    if bytes.starts_with(&[0xFE, 0xFF]) {
        let units: Vec<u16> = bytes[2..].chunks_exact(2).map(|c| u16::from_be_bytes([c[0],c[1]])).collect();
        return String::from_utf16_lossy(&units);
    }
    if bytes.starts_with(&[0xEF, 0xBB, 0xBF]) {
        return String::from_utf8_lossy(&bytes[3..]).into_owned();
    }
    String::from_utf8_lossy(bytes).into_owned()
}
fn language_from_shebang(content: &str) -> Option<usize> {
    let first = content.lines().next()?;
    if !first.starts_with("#!") { return None; }
    let parts: Vec<&str> = first.split_whitespace().collect();
    if parts.is_empty() { return None; }
    if parts[0] == "#!/usr/bin/env" {
        if parts.len() < 2 { return None; }
        let interp = parts[1];
        let env_map: &[(&str,&str)] = &[
            ("perl6","Raku"),("python","Python"),("cython","Cython"),("crystal","Crystal"),("racket","Racket"),("groovy","Groovy"),("elvish","Elvish"),("raku","Raku"),("ruby","Ruby"),("bash","BASH"),("just","Just"),("fish","Fish"),("ksh","Korn shell"),("csh","C Shell"),("sh","Shell"),
        ];
        // longest prefix match
        let mut best: Option<(usize, usize)> = None;
        for (key, lang) in env_map {
            if interp.starts_with(key) {
                if best.map(|(l,_)| key.len() > l).unwrap_or(true) { if let Some(i)=lang_by_name(lang) { best = Some((key.len(), i)); } }
            }
        }
        return best.map(|(_,i)| i);
    }
    let exec = parts[0].strip_prefix("#!")?;
    let full_map: &[(&str,&str)] = &[
        ("/bin/bash","BASH"),("/bin/sh","Shell"),("/bin/zsh","Zsh"),("/bin/ksh","Korn shell"),("/bin/csh","C Shell"),("/bin/fish","Fish"),("/usr/bin/perl","Perl"),("/usr/bin/raku","Raku"),("/usr/bin/perl6","Raku"),("/usr/bin/crystal","Crystal"),
    ];
    for (path, lang) in full_map { if exec == *path { return lang_by_name(lang); } }
    None
}
enum FileOutcome { Counted(usize, Report), Inaccurate(usize), Skipped }
fn process_file(path: &Path, path_str: &str) -> FileOutcome {
    // filename check
    let file_name = path.file_name().map(|s| s.to_string_lossy().to_string()).unwrap_or_default();
    let file_name_lower = file_name.to_lowercase();
    let mut lang_idx: Option<usize> = None;
    if let Some(i) = filename_map().get(&file_name_lower) { lang_idx = Some(*i); }
    let ext_opt: Option<String> = path.extension().map(|e| e.to_string_lossy().to_string());
    if lang_idx.is_none() {
        if let Some(ext) = &ext_opt {
            let key = ext.to_lowercase();
            if let Some(i) = ext_map().get(&key) { lang_idx = Some(*i); }
            else {
                log_warn("tokei::language::language_type", &format!("Unknown extension: {}", key));
                return FileOutcome::Skipped;
            }
        }
    }
    if let Some(idx) = lang_idx {
        match std::fs::read(path) {
            Ok(bytes) => {
                let content = decode_bytes(&bytes);
                let stats = count_normal(idx, &content);
                return FileOutcome::Counted(idx, Report{name: path_str.to_string(), stats});
            }
            Err(e) => {
                log_error("tokei::utils::fs", &format!("Error reading {}:\n    {}", path_str, e));
                return FileOutcome::Inaccurate(idx);
            }
        }
    }
    // no extension: try shebang
    if ext_opt.is_none() {
        match std::fs::read(path) {
            Ok(bytes) => {
                let content = decode_bytes(&bytes);
                if let Some(idx) = language_from_shebang(&content) {
                    let stats = count_normal(idx, &content);
                    return FileOutcome::Counted(idx, Report{name: path_str.to_string(), stats});
                } else { return FileOutcome::Skipped; }
            }
            Err(e) => {
                log_error("tokei::utils::fs", &format!("Error reading {}:\n    {}", path_str, e));
                return FileOutcome::Skipped;
            }
        }
    }
    FileOutcome::Skipped
}

// ------------- languages input parsing validation -------------
#[derive(Deserialize)]
struct InStats { blanks: usize, code: usize, comments: usize, blobs: BTreeMap<String, InStats> }
#[derive(Deserialize)]
struct InReport { stats: InStats, name: String }
#[derive(Deserialize)]
struct InLang { blanks: usize, code: usize, comments: usize, reports: Vec<InReport>, children: BTreeMap<String, Vec<InReport>>, inaccurate: bool }
fn validate_in_stats(s: &InStats) -> bool {
    for (k,v) in &s.blobs { if lang_by_name(k).is_none() { return false; } if !validate_in_stats(v) { return false; } }
    true
}
fn validate_in_report(r: &InReport) -> bool { validate_in_stats(&r.stats) }
fn parse_input_arg(arg: &str) -> Result<(), ()> {
    let content: String = if arg == "stdin" {
        let mut s = String::new();
        match io::stdin().read_to_string(&mut s) { Ok(_)=>s, Err(_)=>return Err(()) }
    } else {
        match std::fs::read_to_string(arg) {
            Ok(s)=>s,
            Err(e) => {
                if e.kind() == io::ErrorKind::IsADirectory { panic!("Couldn't read file: {:?}", e); }
                return Err(());
            }
        }
    };
    let parsed: Result<BTreeMap<String, InLang>, _> = serde_json::from_str(&content);
    let map = match parsed { Ok(m)=>m, Err(_)=>return Err(()) };
    if !map.contains_key("Total") { return Err(()); }
    for (k,v) in &map {
        if k != "Total" && lang_by_name(k).is_none() { return Err(()); }
        for r in &v.reports { if !validate_in_report(r) { return Err(()); } }
        for (ck, reps) in &v.children {
            if lang_by_name(ck).is_none() { return Err(()); }
            for r in reps { if !validate_in_report(r) { return Err(()); } }
        }
    }
    Ok(())
}

// ------------- json output -------------
fn json_escape(s: &str) -> String { serde_json::to_string(s).unwrap() }
fn stats_to_json_output(s: &Stats) -> String {
    let mut blobs = String::from("{");
    let mut first=true;
    for (k,v) in &s.blobs { if !first { blobs.push(','); } first=false; blobs.push_str(&json_escape(k)); blobs.push(':'); blobs.push_str(&stats_to_json_output(v)); }
    blobs.push('}');
    format!("{{\"blanks\":{},\"code\":{},\"comments\":{},\"blobs\":{}}}", s.blanks, s.code, s.comments, blobs)
}
fn stats_to_json_stream(s: &Stats) -> String {
    let mut blobs = String::from("{");
    let mut first=true;
    for (k,v) in &s.blobs { if !first { blobs.push(','); } first=false; blobs.push_str(&json_escape(k)); blobs.push(':'); blobs.push_str(&stats_to_json_stream(v)); }
    blobs.push('}');
    format!("{{\"blanks\":{},\"blobs\":{},\"code\":{},\"comments\":{}}}", s.blanks, blobs, s.code, s.comments)
}
fn report_to_json_output(r: &Report) -> String { format!("{{\"stats\":{},\"name\":{}}}", stats_to_json_output(&r.stats), json_escape(&r.name)) }
fn lang_entry_to_json(e: &LangEntry) -> String {
    let reports = e.reports.iter().map(|r| report_to_json_output(r)).collect::<Vec<_>>().join(",");
    let mut children = String::from("{");
    let mut first=true;
    for (k, reps) in &e.children { if !first { children.push(','); } first=false; children.push_str(&json_escape(k)); children.push(':'); children.push('['); children.push_str(&reps.iter().map(|r| report_to_json_output(r)).collect::<Vec<_>>().join(",")); children.push(']'); }
    children.push('}');
    format!("{{\"blanks\":{},\"code\":{},\"comments\":{},\"reports\":[{}],\"children\":{},\"inaccurate\":{}}}", e.blanks, e.code, e.comments, reports, children, e.inaccurate)
}
fn total_entry(langs: &BTreeMap<String, LangEntry>) -> LangEntry {
    let mut total = LangEntry { name: "Total".to_string(), ..Default::default() };
    for (name, e) in langs {
        total.children.insert(name.clone(), e.reports.clone());
        let (b,c,cm) = e.recursive_totals(); total.blanks+=b; total.code+=c; total.comments+=cm;
        if e.inaccurate { total.inaccurate = true; }
    }
    total
}
fn languages_to_json(langs: &BTreeMap<String, LangEntry>) -> String {
    let mut parts: Vec<String> = Vec::new();
    for (name,e) in langs { parts.push(format!("{}:{}", json_escape(name), lang_entry_to_json(e))); }
    let total = total_entry(langs);
    parts.push(format!("{}:{}", json_escape("Total"), lang_entry_to_json(&total)));
    format!("{{{}}}", parts.join(","))
}

// ------------- number format -------------
fn fmt_num(n: usize, style: &str) -> String {
    if style=="plain" { return n.to_string(); }
    let sep = match style { "commas"=>",", "dots"=>".", "underscores"=>"_", _=>"" };
    if sep.is_empty() { return n.to_string(); }
    let s = n.to_string();
    let mut out = String::new();
    for (i,ch) in s.chars().enumerate() {
        if i>0 && (s.len()-i)%3==0 { out.push_str(sep); }
        out.push(ch);
    }
    out
}

// ------------- table printing -------------
fn truncate_right(s: &str, width: usize) -> String {
    let count = s.chars().count();
    if count > width {
        if width==0 { return String::new(); }
        let mut t: String = s.chars().take(width-1).collect(); t.push('|'); t
    } else { let mut t=s.to_string(); while t.chars().count() < width { t.push(' '); } t }
}
fn truncate_left(s: &str, width: usize) -> String {
    let count = s.chars().count();
    if count > width {
        if width==0 { return String::new(); }
        let skip = count-(width-1);
        let t: String = s.chars().skip(skip).collect(); format!("|{}", t)
    } else { let mut t=s.to_string(); while t.chars().count() < width { t.push(' '); } t }
}
fn pad_right(s: &str, width: usize) -> String { let mut t=s.to_string(); while t.chars().count() < width { t.push(' '); } t }
struct TableCtx { width: usize, num_style: String }
impl TableCtx {
    fn sep_heavy(&self) -> String { "━".repeat(self.width) }
    fn sep_light(&self) -> String { format!("{}", "─".repeat(self.width).dimmed()) }
    fn cell_width(&self) -> usize { self.width - 63 } // 18 at 81
    fn merged_width(&self) -> usize { self.cell_width() + 9 } // 27
    fn name_cell(&self, name: &str, inaccurate: bool, colored_name: bool) -> String {
        let cw = self.cell_width();
        if inaccurate {
            let inner = truncate_right(name, cw-3);
            if colored_name { format!("{}{}", format!("{}", inner.magenta().bold()), "(!)") } else { format!("{}{}", inner, "(!)") }
        } else {
            let inner = truncate_right(name, cw);
            if colored_name { format!("{}", inner.magenta().bold()) } else { inner }
        }
    }
    fn row(&self, first: String, files: Option<String>, lines: usize, code: usize, comments: usize, blanks: usize) -> String {
        let f = files.unwrap_or_default();
        // files field is formatted as right aligned 8, but if files is empty we need blank field: handle by formatting string
        let files_str = if f.is_empty() { " ".repeat(8) } else { format!("{:>8}", f) };
        format!("{} {} {:>12} {:>12} {:>12} {:>12}", first, files_str, fmt_num(lines,&self.num_style), fmt_num(code,&self.num_style), fmt_num(comments,&self.num_style), fmt_num(blanks,&self.num_style))
        // Note: the format above inserts formatted numbers directly ( fmt_num result then padded by {:>12} applies to string length)
    }
    fn row_nums(&self, first: String, files: Option<usize>, lines: usize, code: usize, comments: usize, blanks: usize) -> String {
        // Build with padded formatted numbers
        let files_str = match files { Some(n)=>format!("{:>8}", fmt_num(n,&self.num_style)), None=>" ".repeat(8) };
        format!("{} {} {:>12} {:>12} {:>12} {:>12}", first, files_str, format!("{:>12}", fmt_num(lines,&self.num_style)), format!("{:>12}", fmt_num(code,&self.num_style)), format!("{:>12}", fmt_num(comments,&self.num_style)), format!("{:>12}", fmt_num(blanks,&self.num_style)))
    }
    fn header_row(&self) -> String {
        // plain or coloured
        let cw = self.cell_width();
        // Use same layout as plain: leading space + fields
        // When colour is enabled, colored crate will handle codes; reproducing visible layout
        let lang = format!("{:<width$}", "Language", width=cw);
        let first = format!(" {}", lang.blue().bold());
        format!("{} {} {} {} {} {}", first, format!("{:>8}", "Files").blue().bold(), format!("{:>12}", "Lines").blue().bold(), format!("{:>12}", "Code").blue().bold(), format!("{:>12}", "Comments").blue().bold(), format!("{:>12}", "Blanks").blue().bold())
        // The above format with coloured strings: coloured Display may not pad as expected in original, but visible layout when colour off is exact because coloured returns plain and format! padding already applied? Wait we applied padding before colouring for lang, and for others the format is outside: format!("{:>8}", "Files".blue().bold()) pads based on coloured string; when colour off it's plain and pads correctly. When colour on, padding will differ (matching original style roughly).
    }
}
fn print_languages_list() {
    println!("{}", "━".repeat(72).bold());
    // header
    let header_lang = format!(" {:<38}", "Language");
    let header_ext = format!("{:<30} ", "Extensions");
    println!("{}{}{}", "┃".bold(), format!("{}", header_lang.bold()), format!("{}{}", header_ext.bold(), "┃".bold()));
    println!("{}{}", "┃".bold(), format!("{}{}", "━".repeat(70).bold(), "┃".bold()));
    for l in LANGS {
        let exts = if l.extensions.is_empty() { "<None>".to_string() } else { l.extensions.join(", ") };
        let ext_trunc = if exts.chars().count() > 30 { format!("{}...", exts.chars().take(27).collect::<String>()) } else { exts };
        let line = format!(" {:<38}{:<30} ", l.name, ext_trunc);
        println!("{}{}", "┃".bold(), format!("{}{}", line, "┃".bold()));
    }
    println!("{}", "━".repeat(72).bold());
    println!();
}

// ---------------- main flow ----------------
fn build_cli() -> Command {
    let output_parser = |s: &str| -> Result<String, String> {
        match s {
            "json" => Ok(s.to_string()),
            "cbor" => Err("This version of tokei was compiled without any 'cbor' serialization support, to enable serialization, reinstall tokei with the features flag.\n\n    cargo install tokei --features cbor\n\nIf you want to enable all supported serialization formats, you can use the 'all' feature.\n\n    cargo install tokei --features all\n".to_string()),
            "yaml" => Err("This version of tokei was compiled without any 'yaml' serialization support, to enable serialization, reinstall tokei with the features flag.\n\n    cargo install tokei --features yaml\n\nIf you want to enable all supported serialization formats, you can use the 'all' feature.\n\n    cargo install tokei --features all\n".to_string()),
            _ => Err(format!("\"{}\" is not a supported serialization format", s)),
        }
    };
    Command::new("tokei")
        .version("14.0.0 compiled with serialization support: json")
