        .arg(Arg::new("num_format_style").short('n').long("num-format").value_name("num_format_style").help("Format of printed numbers, i.e., plain (1234, default), commas (1,234), dots (1.234), or underscores (1_234). Cannot be used with --output.").value_parser(clap::builder::PossibleValuesParser::new(["commas","dots","plain","underscores"])).conflicts_with("output"))
        .arg(Arg::new("verbose").short('v').long("verbose").help("Set log output level:\n                        1: to show unknown file extensions,\n                        2: reserved for future debugging,\n                        3: enable file level trace. Not recommended on multiple files").action(ArgAction::Count))
}
#[derive(Debug)]
struct CliDebug {
    matches: clap::ArgMatches,
    columns: Option<usize>,
    files: bool,
    hidden: bool,
    no_ignore: bool,
    no_ignore_parent: bool,
    no_ignore_dot: bool,
    no_ignore_vcs: bool,
    output: Option<String>,
    streaming: Option<String>,
    print_languages: bool,
    sort: Option<String>,
    sort_reverse: bool,
    types: Option<Vec<String>>,
    compact: bool,
    number_format: String,
}
fn main() { std::process::exit(real_main()); }
fn real_main() -> i32 {
    let matches = build_cli().get_matches();
    let verbose = matches.get_count("verbose");
    set_log_level(match verbose { 0=>0, 1=>1, 2=>2, _=>3 });
    let columns: Option<usize> = matches.get_one::<usize>("columns").copied();
    let files_flag = matches.get_flag("files");
    let hidden_flag = matches.get_flag("hidden");
    let languages_flag = matches.get_flag("languages");
    let no_ignore = matches.get_flag("no_ignore");
    let no_ignore_parent = matches.get_flag("no_ignore_parent");
    let no_ignore_dot = matches.get_flag("no_ignore_dot");
    let no_ignore_vcs = matches.get_flag("no_ignore_vcs");
    let compact_flag = matches.get_flag("compact");
    let output_opt: Option<String> = matches.get_one::<String>("output").cloned();
    let streaming_opt: Option<String> = matches.get_one::<String>("streaming").cloned();
    let sort_opt: Option<String> = matches.get_one::<String>("sort").cloned();
    let rsort_opt: Option<String> = matches.get_one::<String>("rsort").cloned();
    let types_opt: Option<Vec<String>> = matches.get_many::<String>("types").map(|v| v.cloned().collect());
    let num_style: String = matches.get_one::<String>("num_format_style").cloned().unwrap_or_else(|| "plain".to_string());
    if log_level() >= 2 {
        let dbg = CliDebug { matches: matches.clone(), columns, files: files_flag, hidden: hidden_flag, no_ignore, no_ignore_parent, no_ignore_dot, no_ignore_vcs, output: output_opt.clone(), streaming: streaming_opt.clone(), print_languages: languages_flag, sort: sort_opt.clone().or(rsort_opt.clone()), sort_reverse: rsort_opt.is_some(), types: types_opt.clone(), compact: compact_flag, number_format: num_style.clone() };
        log_debug("tokei::cli", &format!("CLI Config: {:#?}", dbg));
    }
    if languages_flag { print_languages_list(); return 0; }
    if let Some(fi) = matches.get_one::<String>("file_input") {
        if parse_input_arg(fi).is_err() {
            eprintln!("Error:\n Failed to parse input file: {}\n\nThis version of tokei was compiled without serialization support for the following formats:\n\n    cbor, json, yaml\n\nYou may want to install any comma separated combination of \"cbor,json,yaml\":\n\n    cargo install tokei --features \"cbor,json,yaml\"\n\nOr use the 'all' feature:\n\n    cargo install tokei --features all\n    \n", fi);
            return 1;
        }
    }
    let inputs: Vec<String> = match matches.get_many::<String>("input") { Some(v)=>v.cloned().collect(), None=>vec![".".to_string()] };
    for inp in &inputs {
        if !Path::new(inp).exists() { eprintln!("Error: '{}' not found.", inp); return 1; }
    }
    let excludes: Vec<String> = match matches.get_many::<String>("exclude") { Some(v)=>v.cloned().collect(), None=>Vec::new() };
    // collect files
    let mut entries_map: BTreeMap<String, LangEntry> = BTreeMap::new();
    let mut all_reports: Vec<(String, Report)> = Vec::new(); // language name, report for streaming
    let mut add_outcome = |outcome: FileOutcome, entries_map: &mut BTreeMap<String, LangEntry>, all_reports: &mut Vec<(String,Report)>| {
        match outcome {
            FileOutcome::Counted(idx, report) => {
                let lname = LANGS[idx].name.to_string();
                all_reports.push((lname.clone(), report.clone()));
                let e = entries_map.entry(lname.clone()).or_insert_with(|| LangEntry{name: lname.clone(), ..Default::default()});
                e.blanks += report.stats.blanks; e.code += report.stats.code; e.comments += report.stats.comments;
                for (bname, bstats) in &report.stats.blobs {
                    e.children.entry(bname.clone()).or_default().push(Report{name: report.name.clone(), stats: bstats.clone()});
                }
                e.reports.push(report);
            }
            FileOutcome::Inaccurate(idx) => {
                let lname = LANGS[idx].name.to_string();
                let e = entries_map.entry(lname.clone()).or_insert_with(|| LangEntry{name: lname.clone(), ..Default::default()});
                e.inaccurate = true;
            }
            FileOutcome::Skipped => {}
        }
    };
    // overrides for directory walking
    for inp in &inputs {
        let path = PathBuf::from(inp);
        if path.is_dir() {
            // build walker
            let mut builder = ignore::WalkBuilder::new(&path);
            builder.hidden(!hidden_flag);
            builder.parents(!(no_ignore || no_ignore_parent));
            builder.ignore(!(no_ignore || no_ignore_dot));
            builder.git_ignore(!(no_ignore || no_ignore_vcs));
            builder.git_global(!(no_ignore || no_ignore_vcs));
            builder.git_exclude(!(no_ignore || no_ignore_vcs));
            builder.add_custom_ignore_filename(".tokeignore");
            if !excludes.is_empty() {
                let mut ob = ignore::overrides::OverrideBuilder::new(".");
                let mut ob_failed = false;
                for pat in &excludes {
                    let glob = format!("!{}", pat);
                    if let Err(e) = ob.add(&glob) {
                        log_error("tokei::utils::fs", &format!("error parsing glob '{}': {}", glob, e));
                        ob_failed = true;
                    }
                }
                if !ob_failed {
                    match ob.build() { Ok(ov)=>{ builder.overrides(ov); }, Err(e)=>{ log_error("tokei::utils::fs", &format!("{}", e)); } }
                } else {
                    // still try to build to match original behaviour of ignoring invalid? Original counted files, so skip overrides on failure
                    let _ = &mut ob;
                }
            }
            let walker = builder.build();
            for entry in walker {
                match entry {
                    Ok(en) => {
                        let is_file = en.file_type().map(|f| f.is_file()).unwrap_or(false);
                        if !is_file { continue; }
                        let p = en.path().to_path_buf();
                        let pstr = p.to_string_lossy().to_string();
                        let outcome = process_file(&p, &pstr);
                        add_outcome(outcome, &mut entries_map, &mut all_reports);
                    }
                    Err(e) => {
                        let p = e.path().map(|p| p.to_string_lossy().to_string()).unwrap_or_default();
                        // attempt to extract io error message
                        let msg = format!("{}", e);
                        // ignore crate error Display may already include path; try to format as "<err> reading <path>" if possible
                        // Simplify: if msg contains path, print msg, else format
                        if !p.is_empty() && !msg.contains(&p) {
                            // extract the underlying io message by stripping possible prefix
                            log_error("tokei::utils::fs", &format!("{} reading {}", msg, p));
                        } else {
                            log_error("tokei::utils::fs", &msg);
                        }
                    }
                }
            }
        } else if path.is_file() {
            let outcome = process_file(&path, inp);
            add_outcome(outcome, &mut entries_map, &mut all_reports);
        } else {
            // not file/dir (fifo etc) ignored
            continue;
        }
    }
    // types filtering
    let mut filtered: BTreeMap<String, LangEntry> = BTreeMap::new();
    let type_filter: Option<BTreeSet<String>> = types_opt.as_ref().map(|vec| {
        let mut s = BTreeSet::new();
        for v in vec { for part in v.split(',') { s.insert(part.to_lowercase()); } }
        s
    });
    for (name, e) in entries_map {
        if let Some(f) = &type_filter {
            if !f.contains(&name.to_lowercase()) { continue; }
        }
        filtered.insert(name, e);
    }
    // streaming
    if let Some(stream_mode) = streaming_opt {
        let mode = stream_mode.to_lowercase();
        // filter reports
        let mut reps: Vec<(String,Report)> = all_reports.into_iter().filter(|(lname,_)| {
            if let Some(f)=&type_filter { f.contains(&lname.to_lowercase()) } else { true }
        }).collect();
        reps.sort_by(|a,b| a.1.name.cmp(&b.1.name));
        if mode=="simple" {
            println!("# language                                        path                                          lines         code       comments      blanks   ");
            println!("########## ################################################################################ ############ ############ ############ ############");
            for (lname, rep) in &reps {
                let lines = rep.stats.lines();
                println!("{:>10} {:<80} {:>12} {:>12} {:>12} {:>12}", lname, rep.name, lines, rep.stats.code, rep.stats.comments, rep.stats.blanks);
            }
        } else {
            for (lname, rep) in &reps {
                println!("{{\"language\":{},\"stats\":{{\"name\":{},\"stats\":{}}}}}", json_escape(lname), json_escape(&rep.name), stats_to_json_stream(&rep.stats));
            }
        }
        return 0;
    }
    if let Some(outfmt) = output_opt {
        if outfmt=="json" {
            print!("{}", languages_to_json(&filtered));
            return 0;
        }
    }
    // table
    let any_inaccurate = filtered.values().any(|e| e.inaccurate);
    if any_inaccurate { println!("Note: results can be inaccurate for languages marked with '(!)'"); }
    let width = columns.map(|c| c.max(81)).unwrap_or(81);
    let ctx = TableCtx{ width, num_style: num_style.clone() };
    // sorted list
    let mut sorted: Vec<&LangEntry> = filtered.values().collect();
    // initial alphabetical (BTree already)
    let (sort_key, reverse) = if let Some(s)=&sort_opt { (Some(s.to_lowercase()), false) } else if let Some(s)=&rsort_opt { (Some(s.to_lowercase()), true) } else { (None, false) };
    if let Some(key) = &sort_key {
        sorted.sort_by(|a,b| {
            let ka = match key.as_str() { "files"=>a.reports.len(), "lines"=>a.lines(), "blanks"=>a.blanks, "code"=>a.code, "comments"=>a.comments, _=>0 };
            let kb = match key.as_str() { "files"=>b.reports.len(), "lines"=>b.lines(), "blanks"=>b.blanks, "code"=>b.code, "comments"=>b.comments, _=>0 };
            kb.cmp(&ka)
        });
        if reverse { sorted.reverse(); }
    }
    // display filter
    let display: Vec<&LangEntry> = sorted.into_iter().filter(|e| {
        let (b,c,cm) = e.recursive_totals();
        !(b+c+cm==0 && e.children.is_empty())
    }).collect();
    println!("{}", ctx.sep_heavy());
    println!("{}", ctx.header_row());
    println!("{}", ctx.sep_heavy());
    if files_flag {
        for (idx, e) in display.iter().enumerate() {
            if idx>0 { println!("{}", ctx.sep_light()); }
            // header group
            print_lang_header(&ctx, e, compact_flag);
            println!("{}", ctx.sep_light());
            // files
            let mut reports = e.reports.clone();
            reports.sort_by(|a,b| a.name.cmp(&b.name));
            if compact_flag {
                for r in &reports { print_file_row(&ctx, r, false); }
            } else {
                let simple: Vec<&Report> = reports.iter().filter(|r| r.stats.blobs.is_empty()).collect();
                let complex: Vec<&Report> = reports.iter().filter(|r| !r.stats.blobs.is_empty()).collect();
                for r in &simple { print_file_row(&ctx, r, false); }
                for (i, r) in complex.iter().enumerate() {
                    if simple.is_empty() && i==0 {
                        println!(" {}", r.name);
                    } else {
                        let prelim = format!("-- {} ", r.name);
                        let plen = prelim.chars().count();
                        let line = if plen < ctx.width { format!("{}{}", prelim, "-".repeat(ctx.width-plen)) } else { prelim };
                        println!("{}", line);
                    }
                    // |- parent
                    print_child_file_row(&ctx, &e.name, &r.stats);
                    for (bname, bstats) in &r.stats.blobs { print_child_file_row(&ctx, bname, bstats); }
                    print_file_row(&ctx, r, true);
                }
            }
        }
    } else if compact_flag {
        for e in &display {
            println!("{}", lang_row(&ctx, e));
        }
    } else {
        let childless: Vec<&&LangEntry> = display.iter().filter(|e| e.children.is_empty()).collect();
        let with_children: Vec<&&LangEntry> = display.iter().filter(|e| !e.children.is_empty()).collect();
        for e in &childless { println!("{}", lang_row(&ctx, e)); }
        if !with_children.is_empty() {
            if !childless.is_empty() { println!("{}", ctx.sep_light()); }
            for (i, e) in with_children.iter().enumerate() {
                println!("{}", lang_row(&ctx, e));
                for (cname, reps) in &e.children {
                    // aggregated recursive
                    let mut b=0; let mut ccode=0; let mut cm=0;
                    for r in reps { let (bb,cc,mm)=r.stats.recursive_totals(); b+=bb; ccode+=cc; cm+=mm; }
                    println!("{}", child_row(&ctx, cname, reps.len(), b+ccode+cm, ccode, cm, b));
                }
                let (tb,tc,tcm) = e.recursive_totals();
                println!("{}", total_group_row(&ctx, tb+tc+tcm, tc, tcm, tb));
                if i+1 < with_children.len() { println!("{}", ctx.sep_light()); }
            }
        }
    }
    println!("{}", ctx.sep_heavy());
    // total row
    let total = total_entry(&filtered);
    let (tb,tc,tcm) = (total.blanks, total.code, total.comments);
    let files_total: usize = filtered.values().map(|e| e.reports.len()).sum();
    let first_total = format!(" {}", ctx.name_cell("Total", total.inaccurate, true));
    // coloured total numbers: build manually
    let total_row = format!("{} {} {} {} {} {}", first_total, format!("{}", format!("{:>8}", fmt_num(files_total,&ctx.num_style)).blue()), format!("{}", format!("{:>12}", fmt_num(tb+tc+tcm,&ctx.num_style)).blue()), format!("{}", format!("{:>12}", fmt_num(tc,&ctx.num_style)).blue()), format!("{}", format!("{:>12}", fmt_num(tcm,&ctx.num_style)).blue()), format!("{}", format!("{:>12}", fmt_num(tb,&ctx.num_style)).blue()));
    // When colour off, blue() returns plain; but our numbers order: lines, code, comments, blanks -> row_nums expects lines etc; above we passed tb+tc+tcm as lines, tc code, tcm comments, tb blanks correct
    println!("{}", total_row);
    println!("{}", ctx.sep_heavy());
    0
}
fn lang_row(ctx: &TableCtx, e: &LangEntry) -> String {
    let first = format!(" {}", ctx.name_cell(&e.name, e.inaccurate, true));
    ctx.row_nums(first, Some(e.reports.len()), e.lines(), e.code, e.comments, e.blanks)
}
fn child_row(ctx: &TableCtx, name: &str, files: usize, lines: usize, code: usize, comments: usize, blanks: usize) -> String {
    let cw = ctx.cell_width() - 3;
    let inner = truncate_right(name, cw);
    let first = format!(" |- {}", format!("{}", inner.magenta().bold()));
    ctx.row_nums(first, Some(files), lines, code, comments, blanks)
}
fn total_group_row(ctx: &TableCtx, lines: usize, code: usize, comments: usize, blanks: usize) -> String {
    let first = format!(" {}", pad_right("(Total)", ctx.merged_width()));
    ctx.row_nums(first, None, lines, code, comments, blanks)
}
fn print_lang_header(ctx: &TableCtx, e: &LangEntry, compact: bool) {
    println!("{}", lang_row(ctx, e));
    if !compact {
        for (cname, reps) in &e.children {
            let mut b=0; let mut ccode=0; let mut cm=0;
            for r in reps { let (bb,cc,mm)=r.stats.recursive_totals(); b+=bb; ccode+=cc; cm+=mm; }
            println!("{}", child_row(ctx, cname, reps.len(), b+ccode+cm, ccode, cm, b));
        }
        if !e.children.is_empty() {
            let (tb,tc,tcm) = e.recursive_totals();
            println!("{}", total_group_row(ctx, tb+tc+tcm, tc, tcm, tb));
        }
    }
}
fn print_file_row(ctx: &TableCtx, r: &Report, no_truncate: bool) {
    let cell = if no_truncate { pad_right(&r.name, ctx.merged_width()) } else { truncate_left(&r.name, ctx.merged_width()) };
    let first = format!(" {}", cell);
    println!("{}", ctx.row_nums(first, None, r.stats.lines(), r.stats.code, r.stats.comments, r.stats.blanks));
}
fn print_child_file_row(ctx: &TableCtx, name: &str, stats: &Stats) {
    let cw = ctx.merged_width() - 3;
    let inner = truncate_right(name, cw);
    // For child language rows in files mode, original colours only blob language names that are not the parent? It colours Rust blob but not Markdown parent row etc. Hard to distinguish; we colour if name != ??? Use plain for simplicity except coloured handling would differ only in tty.
    // We will colour the name magenta bold to approximate; when colour off it's plain.
    let first = format!(" |- {}", inner);
    // Use coloured version if colour enabled? colored crate will strip if disabled; to avoid double padding issues, use inner directly (plain). This keeps piped output exact.
    println!("{}", ctx.row_nums(first, None, stats.lines(), stats.code, stats.comments, stats.blanks));
}
