old="fn real_main() -> i32 {\n    let matches = build_cli().get_matches();"
new="""fn real_main() -> i32 {
    let matches = match build_cli().try_get_matches() {
        Ok(m) => m,
        Err(e) => {
            let kind = e.kind();
            let mut text = e.render().to_string();
            // Emulate the smart-usage rendering of the clap version used by the reference:
            // when input was already supplied, a positional in a generated usage (other than the generic one)
            // is shown as required (<input>...) for conflict errors, and for an unknown long argument
            // whose generated usage consists only of the positional.
            let is_help_or_version = matches!(kind, clap::error::ErrorKind::DisplayHelp | clap::error::ErrorKind::DisplayVersion);
            if !is_help_or_version {
                let argv: Vec<String> = std::env::args().skip(1).collect();
                // crude positional detection: a token that is not an option and not consumed as an option value
                let opts_with_val = ["-c","--columns","-e","--exclude","-i","--input","-o","--output","--streaming","-s","--sort","-r","--rsort","-t","--types","-n","--num-format"];
                let mut positional_indices: Vec<usize> = Vec::new();
                let mut i=0usize; let mut after_dd=false;
                while i<argv.len() {
                    let a=&argv[i];
                    if after_dd { positional_indices.push(i); i+=1; continue; }
                    if a=="--" { after_dd=true; i+=1; continue; }
                    if opts_with_val.contains(&a.as_str()) { i+=2; continue; }
                    if a.starts_with("--") {
                        if a.contains('=') { i+=1; continue; } else { i+=1; continue; }
                    }
                    if a.starts_with('-') && a.len()>1 {
                        // combined shorts: if contains a value-taking short, rest/value handling is complex; treat following as consumed only for exact single cases handled above
                        i+=1; continue;
                    }
                    positional_indices.push(i); i+=1;
                }
                let first_line_is_languages = text.lines().next().map(|l| l.contains("'--languages'")).unwrap_or(false);
                let should_transform = match kind {
                    clap::error::ErrorKind::ArgumentConflict => !positional_indices.is_empty() && !first_line_is_languages,
                    clap::error::ErrorKind::UnknownArgument => {
                        // only when the usage line (trimmed) ends with the bare positional usage and input precedes the offending token
                        let usage_line = text.lines().find(|l| l.starts_with("Usage:")).unwrap_or("");
                        let after_usage = usage_line.strip_prefix("Usage: ").unwrap_or("");
                        // usage is "<bin> [input]..." ?
                        let parts: Vec<&str> = after_usage.split_whitespace().collect();
                        parts.len()==2 && parts[1]=="[input]..." && !positional_indices.is_empty()
                    }
                    _ => false,
                };
                if should_transform {
                    // replace only in Usage line
                    let mut out_lines: Vec<String> = Vec::new();
                    for line in text.lines() {
                        if line.starts_with("Usage:") { out_lines.push(line.replace("[input]...", "<input>...")); } else { out_lines.push(line.to_string()); }
                    }
                    text = out_lines.join("\\n");
                    if !text.ends_with('\\n') { text.push('\\n'); }
                }
            }
            if is_help_or_version {
                print!("{}", text); return 0;
            } else {
                eprint!("{}", text); return 2;
            }
        }
    };"""
