    let mut child: Option<(usize, String, String)> = None; // lang, closing, buffer
    for (li, line) in lines.iter().enumerate() {
        let line = *line;
        let mut pos: usize = 0;
        let mut segment_start: usize = 0; // start of current mode segment in this line
        let mut line_had_transition = false;
        loop {
            if let Some((clidx, closing, _)) = child.clone() {
                if let Some(found) = line[pos..].find(&closing) {
                    let cpos = pos + found;
                    let frag = &line[segment_start..cpos];
                    if !frag.is_empty() {
                        if let Some((_,_,buf)) = &mut child { buf.push_str(frag); buf.push('\n'); }
                    }
                    let (cl, _close, buf) = child.take().unwrap();
                    if buf.trim().is_empty() {
                        parent_extra_blanks += buf.lines().count();
                    } else {
                        let counted = count_normal(cl, &buf);
                        blobs.entry(LANGS[cl].name.to_string()).or_default().merge_from(&counted);
                    }
                    let _ = clidx;
                    // parent segment starts at closing tag
                    segment_start = cpos;
                    pos = cpos;
                    line_had_transition = true;
                    // continue as parent
                } else {
                    let frag = &line[segment_start..];
                    if frag.is_empty() {
                        if let Some((_,_,buf)) = &mut child { buf.push('\n'); }
                    } else if let Some((_,_,buf)) = &mut child { buf.push_str(frag); buf.push('\n'); }
                    break;
                }
            }
            // parent mode
            if pos >= line.len() {
                let frag = &line[segment_start..];
                if !frag.is_empty() { parent_text.push_str(frag); parent_text.push('\n'); }
                else if !line_had_transition && child.is_none() && line.is_empty() { parent_text.push('\n'); }
                break;
            }
            // scan parent from pos
            let mut switched = false;
            while pos < line.len() {
                // if inside a frame, handle it
                match parent_stack.last() {
                    Some(Frame::Quote{end, start}) => {
                        let (end_tok, start_tok) = (*end, *start);
                        if line[pos..].starts_with(end_tok) { parent_stack.pop(); pos += end_tok.len(); continue; }
                        if line.as_bytes()[pos]==b'\\' && !start_tok.contains('#') { pos+=1; if pos<line.len() { pos += line[pos..].chars().next().map(|c| c.len_utf8()).unwrap_or(1); } continue; }
                        pos += line[pos..].chars().next().map(|c| c.len_utf8()).unwrap_or(1); continue;
                    }
                    Some(Frame::Comment{start,end,nested,..}) => {
                        let (s_tok,e_tok,nest) = (*start,*end,*nested);
                        if line[pos..].starts_with(e_tok) {
                            if let Some(Frame::Comment{depth,..}) = parent_stack.last_mut() { *depth-=1; if *depth==0 { parent_stack.pop(); } }
                            pos += e_tok.len(); continue;
                        }
                        if nest && line[pos..].starts_with(s_tok) { if let Some(Frame::Comment{depth,..}) = parent_stack.last_mut() { *depth+=1; } pos += s_tok.len(); continue; }
                        pos += line[pos..].chars().next().map(|c| c.len_utf8()).unwrap_or(1); continue;
                    }
                    None => {}
                }
                // outside frames: check tag
                let mut tag_found: Option<(usize, usize, &'static str, &'static str, String)> = None; // start, end, name, closing, tag_text
                for (name, closing) in allowed {
                    let pat = format!("<{}", name);
                    if line[pos..].starts_with(&pat) {
                        let after_name = pos + pat.len();
                        let boundary_ok = if after_name < line.len() { let ch=line.as_bytes()[after_name]; !(ch.is_ascii_alphanumeric() || ch==b'_') } else { true };
                        if boundary_ok {
                            if let Some(gt_rel) = line[pos..].find('>') {
                                let tag_end = pos + gt_rel + 1;
                                let tag_text = line[pos..tag_end].to_string();
                                // closing must exist later in content (search remaining lines)
                                let mut rest_text = String::new(); rest_text.push_str(&line[tag_end..]); for l in &lines[li+1..] { rest_text.push('\n'); rest_text.push_str(l); }
                                if rest_text.contains(closing) { tag_found = Some((pos, tag_end, name, closing, tag_text)); }
                            }
                        }
                        break;
                    }
                }
                if let Some((tstart, tend, name, closing, tag_text)) = tag_found {
                    // append parent fragment including tag
                    let frag = &line[segment_start..tend];
                    if !frag.is_empty() { parent_text.push_str(frag); parent_text.push('\n'); }
                    let child_idx = match name { "script" => script_lang(&tag_text), "style" => lang_attr(&tag_text).unwrap_or_else(|| lang_index("CSS")), "template" => lang_attr(&tag_text).unwrap_or_else(|| lang_index("HTML")), _ => lang_index("JavaScript") };
                    child = Some((child_idx, closing.to_string(), String::new()));
                    pos = tend;
                    segment_start = tend;
                    line_had_transition = true;
                    switched = true;
                    break; // go to child handling for remainder of line
                }
                // syntax tokens
                let mut matched: Option<Token> = None;
                for t in toks { if line[pos..].starts_with(t.text) { matched = Some(t.clone()); break; } }
                if let Some(tok) = matched {
                    match tok.kind {
                        TokKind::Line => { pos = line.len(); break; }
                        TokKind::Block(i) => { let (st,en,ne) = LANGS[lang_idx].blocks[i]; parent_stack.push(Frame::Comment{start:st,end:en,nested:ne,depth:1}); pos += tok.text.len(); continue; }
                        TokKind::Quote(i) => {
                            // escaped quote check
                            let mut bs=0usize; let mut bp=pos; while bp>0 && line.as_bytes()[bp-1]==b'\\' { bs+=1; bp-=1; }
                            if bs%2==1 { pos += tok.text.len(); continue; }
                            let (st,en) = LANGS[lang_idx].quotes[i]; parent_stack.push(Frame::Quote{end:en,start:st}); pos += tok.text.len(); continue;
                        }
                        TokKind::Doc => { pos += tok.text.len(); continue; }
                    }
                }
                pos += line[pos..].chars().next().map(|c| c.len_utf8()).unwrap_or(1);
            }
            if switched { continue; }
            // finished parent scanning for this line
            let frag = &line[segment_start..];
            if !frag.is_empty() { parent_text.push_str(frag); parent_text.push('\n'); }
            else if !line_had_transition && child.is_none() && line.is_empty() { parent_text.push('\n'); }
            break;
        }
    }
    // unterminated child: treat its buffer as parent content (matching reference: no blob, parent counts those lines)
    if let Some((_cl, _closing, buf)) = child.take() {
        parent_text.push_str(&buf);
    }
    let mut stats = count_simple(lang_idx, &parent_text);
    stats.blanks += parent_extra_blanks;
    stats.blobs = blobs;
    stats
}

