    m,s=pty.openpty(); p=subprocess.Popen([b]+args,stdout=s,stderr=s,stdin=s); os.close(s); out=b""
    while True:
        try: d=os.read(m,4096)
        except: break
        if not d: break
        out+=d
    p.wait(); return out
for args in [["--streaming","simple","/tmp/test1"],["--streaming","json","/tmp/test1"]]:
    a=run("/tmp/origbin/executable",args); b=run("/tmp/bintest/executable",args); print(args, a==b, repr(a[:300]))
PY
"}

